    s += exps[i];
  }
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  gap = 12;
  bw = (w - gap * (logits.length + 1)) / logits.length;
  for (i = 0; i < logits.length; i++) {
    p = exps[i] / s;
    bh = p * (h - 36);
    ctx.fillStyle = i === 0 ? "#c4512c" : "#1f4b99";
    ctx.fillRect(gap + i * (bw + gap), h - 16 - bh, bw, bh);
  }
}

