    var m = xs[0], k, out = [], acc = 0;
    for (k = 1; k < xs.length; k++) if (xs[k] > m) m = xs[k];
    for (k = 0; k < xs.length; k++) { out[k] = Math.exp(xs[k] - m); acc += out[k]; }
    for (k = 0; k < xs.length; k++) out[k] = out[k] / acc;
    return out;
