  var order = [0, 1, 2], i, j, tmp, a, b, tot, best = -1e9, phrase = "", bi = 0;
  for (i = 0; i < 3; i++) for (j = i + 1; j < 3; j++) if (s1[order[j]] > s1[order[i]]) {
    tmp = order[i]; order[i] = order[j]; order[j] = tmp;
  }
  for (a = 0; a < width; a++) {
    i = order[a];
