  }
  ctx.stroke();
  ctx.fillStyle = "#2e7d32";
  ctx.beginPath();
  ctx.arc(X(best), Y(f[best]), 5, 0, 6.2832);
  ctx.fill();
  ctx.fillStyle = "#5c564c";
